  const [query, setQuery] = useState(requestedQuery);
  const [pages, setPages] = useState<VisitorTrace[]>([]);
  const [cursor, setCursor] = useState("");
  const [toast, setToast] = useState("");

  useEffect(() => {
    setInput(subject || requestedQuery);
