func (s *Server) eventCatalog(w http.ResponseWriter, r *http.Request) {
	// Every heavy read runs under the analytical deadline. Without it a widened
	// range holds a connection until the browser gives up, and the reader sees a
	// hung page rather than the advice the timeout carries.
	reportCtx, cancelReport := s.analyticalContext(r)
	defer cancelReport()
	siteID, err := s.resolveSite(r, "siteID")
	if err != nil {
		writeError(w, 404, "UNKNOWN_SITE", "site not found")
		return
	}
	environment := requestEnvironment(r)
	// A metric uses an event when its definition names it as event_name, at the
	// top or inside a ratio's numerator or denominator. That is a comparison of
	// the name, not a search of the definition's text: as text, "purchase" is
	// found inside "purchase_completed", and a LIKE reads each "_" as any one
	// character, so the count said an event was in use when it was not.
	rows, err := s.DB.Query(reportCtx, `SELECT d.name,d.description,d.owner,d.current_version,d.deprecated,v.schema,min(e.event_timestamp),max(e.event_timestamp),count(e.event_id),count(*) FILTER(WHERE e.event_timestamp>=now()-interval '30 days'),
		(SELECT count(*) FROM semantic_metrics m WHERE m.site_id=d.site_id AND jsonb_path_exists(m.definition,'$.**.event_name ? (@ == $name)',jsonb_build_object('name',d.name))),
		(SELECT count(*) FROM metric_goals g WHERE g.site_id=d.site_id AND g.metric_name IN (SELECT name FROM semantic_metrics m WHERE m.site_id=d.site_id AND jsonb_path_exists(m.definition,'$.**.event_name ? (@ == $name)',jsonb_build_object('name',d.name))))
		FROM event_definitions d JOIN event_contract_versions v ON v.site_id=d.site_id AND v.event_name=d.name AND v.version=d.current_version
		LEFT JOIN raw_events e ON e.site_id=d.site_id AND e.event_name=d.name AND e.environment=$2 WHERE d.site_id=$1
		GROUP BY d.site_id,d.name,d.description,d.owner,d.current_version,d.deprecated,v.schema ORDER BY d.name`, siteID, environment)
	if err != nil {
		writeError(w, 500, "QUERY_FAILED", err.Error())
		return
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var name, description, owner string
		var version int
		var deprecated bool
		var schema []byte
		var firstSeen, lastSeen *time.Time
		var volume, volume30, metricUses, goalUses int64
		if err := rows.Scan(&name, &description, &owner, &version, &deprecated, &schema, &firstSeen, &lastSeen, &volume, &volume30, &metricUses, &goalUses); err != nil {
			writeError(w, 500, "QUERY_FAILED", err.Error())
			return
		}
		var schemaValue any
		_ = json.Unmarshal(schema, &schemaValue)
		status := "healthy"
		if deprecated {
			status = "deprecated"
		} else if volume30 == 0 {
			status = "inactive"
		}
		out = append(out, map[string]any{"name": name, "description": description, "owner": owner, "current_version": version, "status": status, "schema": schemaValue, "first_seen": firstSeen, "last_seen": lastSeen, "volume": volume, "volume_30d": volume30, "used_by": map[string]any{"metrics": metricUses, "goals": goalUses}})
	}
	if err := rows.Err(); err != nil {
		writeError(w, 500, "QUERY_FAILED", err.Error())
		return
	}
	writeJSON(w, 200, out)
}

func (s *Server) dataLineage(w http.ResponseWriter, r *http.Request) {
	siteID, err := s.resolveSite(r, "siteID")
	if err != nil {
		writeError(w, 404, "UNKNOWN_SITE", "site not found")
		return
	}
	metricRows, err := s.DB.Query(r.Context(), `SELECT name,label,definition FROM semantic_metrics WHERE site_id=$1 ORDER BY name`, siteID)
	if err != nil {
		writeError(w, 500, "QUERY_FAILED", err.Error())
		return
	}
	defer metricRows.Close()
	nodes := []map[string]any{}
	edges := []map[string]any{}
	for metricRows.Next() {
		var name, label string
		var raw []byte
		if err := metricRows.Scan(&name, &label, &raw); err != nil {
			writeError(w, 500, "QUERY_FAILED", err.Error())
			return
		}
		nodes = append(nodes, map[string]any{"id": "metric:" + name, "kind": "metric", "label": label})
		var def semanticDefinition
		if json.Unmarshal(raw, &def) == nil {
			nodes, edges = appendLineageSources(nodes, edges, name, def, 0)
		}
	}
	if err := metricRows.Err(); err != nil {
		writeError(w, 500, "QUERY_FAILED", err.Error())
		return
	}
	goalRows, err := s.DB.Query(r.Context(), `SELECT id,name,metric_name FROM metric_goals WHERE site_id=$1`, siteID)
	if err != nil {
		writeError(w, 500, "QUERY_FAILED", err.Error())
		return
	}
	defer goalRows.Close()
	for goalRows.Next() {
		var id uuid.UUID
		var name, metric string
		if err := goalRows.Scan(&id, &name, &metric); err != nil {
			writeError(w, 500, "QUERY_FAILED", err.Error())
			return
		}
		nodes = append(nodes, map[string]any{"id": "goal:" + id.String(), "kind": "goal", "label": name})
		edges = append(edges, map[string]any{"from": "metric:" + metric, "to": "goal:" + id.String(), "relation": "measures"})
	}
	if err := goalRows.Err(); err != nil {
		writeError(w, 500, "QUERY_FAILED", err.Error())
		return
	}
	writeJSON(w, 200, map[string]any{"nodes": dedupeLineageNodes(nodes), "edges": edges})
}

// appendLineageSources draws an edge from everything a metric reads to the
// metric. A ratio keeps its sources inside numerator and denominator, and a
// walk that stopped at the top level left a conversion rate with no source at
// all, which the lineage table showed as a metric nobody feeds. The walk goes
// as deep as validateSemanticDefinition lets a definition nest, and the same
// event or metric reached twice draws one edge.
func appendLineageSources(nodes, edges []map[string]any, metric string, def semanticDefinition, depth int) ([]map[string]any, []map[string]any) {
	if depth > 5 {
		return nodes, edges
	}
	if def.EventName != "" {
		nodes = append(nodes, map[string]any{"id": "event:" + def.EventName, "kind": "event", "label": def.EventName})
		edges = appendLineageEdge(edges, map[string]any{"from": "event:" + def.EventName, "to": "metric:" + metric, "relation": "aggregates"})
	}
	if def.Metric != "" {
		edges = appendLineageEdge(edges, map[string]any{"from": "metric:" + def.Metric, "to": "metric:" + metric, "relation": "formula"})
	}
	for _, side := range []*semanticDefinition{def.Numerator, def.Denominator} {
		if side != nil {
			nodes, edges = appendLineageSources(nodes, edges, metric, *side, depth+1)
		}
	}
	return nodes, edges
}

func appendLineageEdge(edges []map[string]any, edge map[string]any) []map[string]any {
	for _, existing := range edges {
		if existing["from"] == edge["from"] && existing["to"] == edge["to"] && existing["relation"] == edge["relation"] {
			return edges
		}
	}
	return append(edges, edge)
}

func dedupeLineageNodes(in []map[string]any) []map[string]any {
	seen := map[string]bool{}
	out := []map[string]any{}
	for _, node := range in {
		id := fmt.Sprint(node["id"])
		if !seen[id] {
			seen[id] = true
			out = append(out, node)
		}
	}
	return out
}

